<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { locale } from '../i18n'
import { getEvaluationStatus, runEvaluation, seedEvaluation } from '../api/evaluation'
import type { EvaluationReport, EvaluationStatus, EvaluationStrategy } from '../api/evaluation'
const tr = (zh: string, en: string) => locale.value === 'zh-CN' ? zh : en
const status = ref<EvaluationStatus | null>(null)
const report = ref<EvaluationReport | null>(null)
const selected = ref<EvaluationStrategy | null>(null)
const queryRecords = ref<HTMLElement>()
watch(selected, async value => { if (value) { await nextTick(); queryRecords.value?.scrollIntoView({ block: 'start', behavior: 'instant' }) } })
const split = ref('all'), topK = ref(3), real = ref(false), busy = ref(''), error = ref('')
const budgetMs = ref(120000)
const ready = computed(() => !!(real.value ? status.value?.snapshots.realReady : status.value?.snapshots.demoReady))
watch([split, topK, real, budgetMs], () => { report.value = null; selected.value = null; error.value = '' })
const metric = (n: number | null | undefined) => n == null ? '—' : n.toFixed(3)
const strategyName = (name: string) => name === 'keyword' ? tr('关键词', 'Keyword') : name === 'vector' ? tr('精确向量', 'Exact vector') : name === 'hybrid' ? 'RRF' : tr('RRF + 重排', 'RRF + rerank')
async function action(name: string, work: () => Promise<void>) {
  if (busy.value) return
  busy.value = name; error.value = ''
  try { await work() } catch (reason) { error.value = reason instanceof Error ? reason.message : tr('评测操作失败', 'Evaluation failed') }
  finally { busy.value = '' }
}
const refresh = () => action('refresh', async () => { status.value = null; status.value = await getEvaluationStatus() })
const seed = () => action('seed', async () => { report.value = null; selected.value = null; status.value = await seedEvaluation(real.value) })
const run = () => action('run', async () => { report.value = null; selected.value = null; report.value = await runEvaluation(split.value, topK.value, real.value, budgetMs.value) })
function download() {
  if (!report.value) return
  const url = URL.createObjectURL(new Blob([JSON.stringify(report.value, null, 2)], { type: 'application/json' }))
  const link = document.createElement('a'); link.href = url; link.download = `lesson13-evaluation-${report.value.datasetVersion}.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000)
}
onMounted(refresh)
</script>

<template>
  <section class="evaluation" aria-labelledby="evaluation-title" :aria-busy="!!busy">
    <header><div><p class="eyebrow">{{ tr('第十三课 · 固定集评测', 'LESSON 13 · FIXED DATASET') }}</p><h2 id="evaluation-title">{{ tr('用同一组问题，比较四种方案', 'Four approaches, one question set') }}</h2><p>{{ tr('调参集与留出集分开报告，保留失败样本；不预设混合检索一定更好。', 'Report tuning and holdout sets separately. Keep failures; hybrid retrieval is not assumed to win.') }}</p></div><button :disabled="!!busy" @click="refresh">{{ tr('刷新评测状态', 'Refresh evaluation status') }}</button></header>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <div class="dataset-strip"><div><small>{{ tr('资料快照', 'Dataset snapshot') }}</small><strong>{{ status?.datasetVersion || '—' }}</strong></div><div><small>{{ tr('固定问题', 'Fixed questions') }}</small><strong>{{ status?.questionCount ?? '—' }}</strong></div><div><small>{{ tr('调参 / 留出', 'Tuning / holdout') }}</small><strong>{{ status ? `${status.splits.tuning} / ${status.splits.holdout}` : '—' }}</strong></div><div><small>{{ tr('所选模型快照', 'Selected model snapshot') }}</small><strong>{{ ready ? tr('已准备', 'Ready') : tr('尚未准备', 'Not ready') }}</strong></div></div>
    <div class="controls"><label>{{ tr('问题分组', 'Question split') }}<select v-model="split" :disabled="!!busy"><option value="all">{{ tr('全部（分组报告）', 'All (separate groups)') }}</option><option value="tuning">{{ tr('调参集', 'Tuning') }}</option><option value="holdout">{{ tr('留出集', 'Holdout') }}</option></select></label><label>{{ tr('评测 Top K', 'Evaluation Top K') }}<select v-model.number="topK" :disabled="!!busy"><option v-for="k in [1,3,5]" :key="k" :value="k">{{ k }}</option></select></label><label>{{ tr("整轮评测预算", "Batch evaluation budget") }}<select v-model.number="budgetMs" :disabled="!!busy"><option :value="30000">30 s</option><option :value="60000">60 s</option><option :value="120000">120 s</option></select></label><label class="check"><input v-model="real" type="checkbox" :disabled="!!busy || !status?.realAvailable" />{{ tr('真实 Embedding（会调用模型）', 'Live embedding (model calls)') }}</label></div>
    <p class="boundary">{{ real ? tr('只向配置的模型发送合成评测资料。准备与运行会产生真实请求；同题在不同方案间复用查询向量，并报告实际调用数。', 'Only synthetic evaluation data is sent to the configured model. Preparation and evaluation make live calls. Query vectors are reused across approaches; actual calls are reported.') : tr('当前为真实 PostgreSQL + 确定性演示向量：用于验证工程闭环，不证明中文语义质量。重排方式以逐题记录为准。', 'Real PostgreSQL with deterministic demo vectors verifies the engineering flow, not semantic quality. Per-query records identify the reranker actually used.') }}</p>
    <div class="actions"><button :disabled="!!busy || !status" @click="seed">{{ busy === 'seed' ? tr('正在准备资料…', 'Preparing…') : tr('准备所选模型的合成资料', 'Prepare synthetic data for selected model') }}</button><button class="primary" :disabled="!!busy || !ready" @click="run">{{ busy === 'run' ? tr('正在比较四种方案…', 'Comparing four approaches…') : tr('运行固定集评测', 'Run fixed-set evaluation') }}</button><button :disabled="!!busy || !report" @click="download">{{ tr('导出评测 JSON', 'Export evaluation JSON') }}</button></div>
    <template v-if="report"><p class="report-status" role="status">{{ report.complete ? tr('本轮评测已完成', 'Evaluation complete') : tr('本轮为部分结果，不能作为完整验收', 'Partial results — not a complete acceptance run') }} · {{ report.queryCount }} {{ tr('问', 'questions') }} · {{ report.elapsedMs }} ms</p><p class="model-meta">{{ report.modelIdentity }} · {{ tr('向量调用 / 缓存复用', 'Embedding calls / cache hits') }} {{ report.embeddingCalls }} / {{ report.embeddingCacheHits }}</p><p class="model-meta">{{ tr('重排器 / 调用数', 'Reranker / calls') }} · {{ report.rerankerIdentity }} / {{ report.rerankerCalls }} · {{ report.realReranker ? tr('真实重排已成功执行', 'Live reranking executed') : tr('未取得真实重排成功结果', 'No successful live reranking result') }}</p><p class="boundary">{{ locale === 'zh-CN' ? report.boundary : 'Synthetic 22-question teaching dataset; real PostgreSQL, serial execution and shared per-query embedding cache. Recall/nDCG exclude no-answer cases; MRR includes their zero scores. Forbidden candidates and execution errors must be zero. Actual model identities and per-query fallbacks are shown above and below. This small dataset is not a production quality or load benchmark.' }}</p>
      <div class="table-scroll"><table><caption>{{ tr('检索指标对照（— 表示无定义）', 'Retrieval comparison (— means undefined)') }}</caption><thead><tr><th>{{ tr('方案 / 分组', 'Approach / split') }}</th><th>Recall@{{ topK }}</th><th>MRR</th><th>nDCG</th><th>p95 ms</th><th>{{ tr('违规 / 错误', 'Violations / errors') }}</th><th>{{ tr('逐题记录', 'Query records') }}</th></tr></thead><tbody><tr v-for="strategy in report.strategies" :key="`${strategy.mode}-${strategy.split}`"><th>{{ strategyName(strategy.mode) }}<small>{{ strategy.split }}</small></th><td>{{ metric(strategy.metrics.recall) }}</td><td>{{ metric(strategy.metrics.mrr) }}</td><td>{{ metric(strategy.metrics.ndcg) }}</td><td>{{ metric(strategy.metrics.p95Ms) }}</td><td :class="{violated: strategy.metrics.forbiddenCount || strategy.metrics.errorCount}">{{ strategy.metrics.forbiddenCount }} / {{ strategy.metrics.errorCount }}</td><td><button @click="selected = strategy">{{ tr('查看逐题结果', 'Inspect query results') }} · {{ strategy.metrics.evaluatedCount }}</button></td></tr></tbody></table></div>
      <section v-if="selected" ref="queryRecords" class="query-records" aria-label="Evaluation query records"><header><h3>{{ strategyName(selected.mode) }} · {{ selected.split }}</h3><button @click="selected = null">{{ tr('关闭逐题结果', 'Close query results') }}</button></header><article v-for="item in selected.queries" :key="item.queryId"><strong>{{ item.queryId }} · {{ item.question }}</strong><p v-if="item.error" class="error">{{ item.error }}</p><p v-else>Recall {{ metric(item.score?.recall) }} · MRR {{ metric(item.score?.mrr) }} · nDCG {{ metric(item.score?.ndcg) }} · {{ item.elapsedMs }} ms</p><p v-if="item.score?.noAnswer">{{ tr('无答案组：单列，不参与 Recall 零分母平均。', 'No-answer group: excluded from undefined recall averages.') }}</p><p>{{ item.reranker }}<span v-for="reason in item.degradations" :key="reason"> · {{ reason }}</span></p><details><summary>{{ tr('候选块身份', 'Candidate chunk identities') }} · {{ item.ranking.length }}</summary><ol><li v-for="id in item.ranking" :key="id"><code>{{ id }}</code></li></ol></details></article></section>
    </template>
  </section>
</template>

<style scoped>
h2{scroll-margin-top:100px}

.evaluation{border:1px solid #dfe7df;border-radius:14px;background:#fffdf9;padding:26px;margin:36px 0;color:#243c36}.evaluation>header,.query-records>header{display:flex;justify-content:space-between;align-items:start;gap:20px}.eyebrow{font-size:11px;letter-spacing:.12em;color:#377764;font-weight:700;margin:0 0 10px}h2{font-size:25px;letter-spacing:-.03em;margin:0 0 12px}header p:not(.eyebrow){font-size:12px;color:#7a877b;line-height:1.8;max-width:750px}.dataset-strip{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:20px;border-top:1px solid #e1e8df;border-bottom:1px solid #e1e8df;padding:20px 0;margin:20px 0}.dataset-strip small{display:block;font-size:10px;color:#879182;margin-bottom:7px}.dataset-strip strong{font-size:15px;font-weight:500;overflow-wrap:anywhere}.controls,.actions{display:flex;align-items:center;flex-wrap:wrap;gap:14px}.controls{align-items:end}label{display:block;font-size:11px;font-weight:600}select{display:block;border:1px solid #dce5da;border-radius:7px;padding:9px;font:inherit;color:#37503f;background:white;margin-top:8px}.check{display:flex;gap:7px;align-items:center;min-height:37px}input{accent-color:#377764}.boundary,.model-meta{font-size:11px;line-height:1.8;color:#82907d;overflow-wrap:anywhere}.boundary{background:#f4f6ee;border-radius:7px;padding:12px;margin:18px 0}.actions{gap:8px}button{border:1px solid #dfe7df;border-radius:7px;padding:9px 12px;font:inherit;font-size:11px;cursor:pointer;background:white;color:#36533e}button:hover:not(:disabled){background:#edf4e9;border-color:#95b49a}button:disabled{opacity:.5;cursor:wait}.primary{background:#377764;color:white}.primary:hover:not(:disabled){background:#285e4f}button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #7dafa0;outline-offset:2px}.report-status{font-size:13px;color:#377764;margin:24px 0 10px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left;margin:20px 0}caption{text-align:left;color:#879381;font-size:11px;padding:0 0 14px}th,td{padding:13px 10px;border-bottom:1px solid #e3e9dd;font-variant-numeric:tabular-nums}thead{background:#f3f6ed;color:#6d8267}th{font-weight:500}th small{display:block;color:#8c9788;font-size:10px;margin-top:5px}.violated{color:#aa5642;font-weight:700}.error{background:#fff0e9;padding:12px;color:#954d3c;font-size:12px;line-height:1.7;border-radius:7px}.query-records{border:1px solid #dce6d6;border-radius:10px;background:#f8faf3;padding:20px;margin-top:20px}.query-records h3{font-size:16px;margin:0}.query-records article{border-top:1px solid #e0e8d9;padding:18px 0;margin-top:14px}.query-records strong{font-size:12px}.query-records p,summary{font-size:11px;line-height:1.7;color:#7d8d73}.query-records code{font-size:10px;overflow-wrap:anywhere}.query-records li{margin:9px 0}summary{cursor:pointer}@media(max-width:680px){.evaluation{padding:18px}.evaluation>header{flex-direction:column;gap:8px}h2{font-size:22px}.dataset-strip{grid-template-columns:1fr 1fr}.controls{align-items:start}.check{flex-basis:100%}.query-records{padding:14px}}
</style>
